export const characterProfileTemplateSchema=z.strictObject({schemaVersion:z.literal(1).default(1),sections:z.array(customSectionSchema).max(1000)});
export function validateCustomSections(sections:CustomSection[]){
 const sectionIds=new Set(sections.map(section=>section.id)),fieldIds=new Set<string>();
 if(sectionIds.size!==sections.length)throw new Error('duplicate_section_id');
 for(const section of sections){
  if(section.parentId&&!sectionIds.has(section.parentId))throw new Error('missing_parent_section');
  let parentId=section.parentId;const seen=new Set([section.id]);
  while(parentId){if(seen.has(parentId))throw new Error('section_cycle');seen.add(parentId);const parent=sections.find(candidate=>candidate.id===parentId);if(!parent)throw new Error('missing_parent_section');parentId=parent.parentId;}
  for(const field of section.fields){if(fieldIds.has(field.id))throw new Error('duplicate_field_id');fieldIds.add(field.id);}
 }
 return sections;
}
export function applyCharacterProfileTemplate(existing:CustomSection[],template:unknown):CustomSection[]{
 const current=validateCustomSections(z.array(customSectionSchema).max(1000).parse(existing));
 const replacement=characterProfileTemplateSchema.parse(template).sections;
 validateCustomSections(replacement);
 const currentFields=new Map(current.flatMap(section=>section.fields.map(field=>[field.id,field] as const)));
 const next=structuredClone(replacement).map(section=>({...section,fields:section.fields.map(field=>{
  const old=currentFields.get(field.id);
  // A stable field ID owns its value contract. Template presentation may move or relabel it, but cannot reinterpret the saved value.
  return old?{...field,type:old.type,value:structuredClone(old.value),repeatable:old.repeatable}:field;
 })}));
 const nextFields=new Set(next.flatMap(section=>section.fields.map(field=>field.id)));
 const bySection=new Map(next.map(section=>[section.id,section]));
 for(const oldSection of current){
  const leftovers=oldSection.fields.filter(field=>!nextFields.has(field.id)).map(field=>({...structuredClone(field),archived:true}));
  if(!leftovers.length)continue;
  const target=bySection.get(oldSection.id);
  if(target)target.fields.push(...leftovers);
  else{const archived={...structuredClone(oldSection),parentId:null,archived:true,fields:leftovers};next.push(archived);bySection.set(archived.id,archived);}
 }
 return validateCustomSections(next);
}
export function data<K extends Kind>(entity:Entity,kind:K):Data<K>{
 if(entity.kind!==kind)throw new Error('entity_kind_mismatch');
 return dataSchemas[kind].parse(entity.data) as Data<K>;
}
export function validateEntity(raw:unknown):Entity{
 const e=entitySchema.parse(raw);e.data=dataSchemas[e.kind].parse(e.data) as Entity['data'];
 if(e.kind==='media'){const m=data(e,'media');mediaBytes(m.mime,m.body);}
 if(e.kind==='item'){const d=data(e,'item');if(d.loaded>d.magazine)throw new Error('ammo_capacity');if(d.possessorId&&(d.locationId||d.containerId)||d.locationId&&d.containerId)throw new Error('ambiguous_item_location');if(['phone','key','weapon','firearm','magazine','document','camera','computer','storage-media','vehicle'].includes(d.category)&&d.quantity!==1)throw new Error('unique_item_quantity');if(d.category==='firearm'&&d.chamberState==='loaded'&&!d.chamberAmmoType&&d.ammoType)d.chamberAmmoType=d.ammoType;if(d.category!=='firearm'&&d.installedMagazineId)throw new Error('magazine_install_target');if(['firearm','weapon'].includes(d.category)&&d.concealed&&!d.concealmentContextId)throw new Error('concealment_context_required');e.data=d as Entity['data'];}
 if(e.kind==='injury'){const d=data(e,'injury');if(!d.onsetAt)d.onsetAt=d.startedAt;if(!d.knownByIds.includes(d.characterId)&&d.healthVisibility!=='hidden')d.knownByIds.push(d.characterId);e.data=d as Entity['data'];}
 if(e.kind==='vehicle'){const d=data(e,'vehicle');if(d.keyId&&!d.keyIds.includes(d.keyId))d.keyIds.unshift(d.keyId);if(d.stolen&&d.theftStatus==='none')d.theftStatus='stolen';if(['stolen','reported'].includes(d.theftStatus))d.stolen=true;if(d.theftStatus==='recovered')d.stolen=false;if(d.locationId&&d.routeState)throw new Error('ambiguous_vehicle_location');if(d.custodyRole&&!d.custodianId||d.custodianId&&!d.custodyRole)throw new Error('incomplete_vehicle_custody');e.data=d as Entity['data'];}
 if(e.kind==='evidence'){const d=data(e,'evidence');if(d.objectId&&!d.objectIds.includes(d.objectId))d.objectIds.unshift(d.objectId);if(d.caseId&&!d.caseIds.includes(d.caseId))d.caseIds.unshift(d.caseId);d.sourceLocationId??=d.locationId;if(d.destroyed)d.condition='destroyed';else if(d.contaminated&&d.condition==='intact')d.condition='contaminated';d.destroyed=d.destroyed||d.condition==='destroyed';d.contaminated=d.contaminated||d.condition==='contaminated';d.knownByIds=[...new Set([...d.knownByIds,...d.discoveredBy])];e.data=d as Entity['data'];}
 if(e.kind==='faction'){const d=data(e,'faction');d.territoryIds=[...new Set([...d.territoryIds,...d.jurisdictionIds])];for(const characterId of d.memberIds)if(!d.memberships.some(row=>row.characterId===characterId))d.memberships.push({characterId,rankId:null,status:'active',public:true,joinedAt:null,endedAt:null,knownByIds:[characterId],note:'Legacy membership'});for(const membership of d.memberships){if(['probationary','active','suspended'].includes(membership.status)&&!d.memberIds.includes(membership.characterId))d.memberIds.push(membership.characterId);if(!membership.knownByIds.includes(membership.characterId))membership.knownByIds.push(membership.characterId);}if(new Set(d.memberships.map(row=>row.characterId)).size!==d.memberships.length)throw new Error('duplicate_faction_membership');const ranks=new Set(d.hierarchy.map(row=>row.id)),goals=new Set(d.goals.map(row=>row.id));if(ranks.size!==d.hierarchy.length||goals.size!==d.goals.length)throw new Error('duplicate_faction_local_id');for(const rank of d.hierarchy)if(rank.parentRankId&&!ranks.has(rank.parentRankId))throw new Error('faction_rank_parent_missing');for(const membership of d.memberships)if(membership.rankId&&!ranks.has(membership.rankId))throw new Error('faction_rank_missing');for(const hook of d.eventHooks)if(hook.goalId&&!goals.has(hook.goalId))throw new Error('faction_goal_missing');if(d.enemyIds.some(id=>d.allyIds.includes(id)))throw new Error('faction_ally_enemy_conflict');e.data=d as Entity['data'];}
 if(e.kind==='combat'){const d=data(e,'combat');if(!d.turnOrder.length)d.turnOrder=[...d.participants];for(const [index,participantId] of d.participants.entries()){d.sides[participantId]??=index===0?'side-a':'side-b';d.positions[participantId]??=0;d.actorStates[participantId]??={side:d.sides[participantId]!,position:d.positions[participantId]!,zoneId:null,stance:'standing',cover:d.cover[participantId]??0,coverSourceId:null,visibleTargetIds:d.participants.filter(id=>id!==participantId),restrainedBy:null,restraintItemId:null,readiedWeaponId:null,actionPoints:1,availableActions:[...tacticalActionNames],goal:'survive',fear:0,morale:50,surrenderThreshold:15,fleeThreshold:30,escaped:false,surrendered:false};}e.data=d as Entity['data'];}
 validateCustomSections(e.data.sections as CustomSection[]);
 return e;
}
